<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateAsset\Application\Usecase\Update;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\TemplateAssetRef;
use Civi\Lughauth\Features\Document\TemplateAsset\Application\Service\Visibility\TemplateAssetVisibilityService;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\Gateway\TemplateAssetWriteGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class TemplateAssetUpdateUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly TemplateAssetVisibilityService $visibility,
        private readonly TemplateAssetWriteGateway $writer,
    ) {
    }

    public function allowUpdate(?TemplateAssetRef $ref = null): Allow
    {
        $this->logDebug("Check allow update usecase for Template asset");
        $span = $this->startSpan("Check allow update usecase for Template asset");
        try {
            $result = $this->dispatcher->dispatch(new TemplateAssetUpdateAllowDecision(Allow::allowed('update', 'Allowed to update by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function fixedFields(?TemplateAssetRef $ref = null): array
    {
        $this->logDebug("Check fixed fields for update usecase for Template asset");
        $span = $this->startSpan("Check fixed fields for update usecase for Template asset");
        try {
            return $this->visibility->fieldsToFix($ref);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function update(string $uid, TemplateAssetUpdateParams $params): TemplateAssetUpdateResult
    {
        $this->logDebug("Run update usecase for Template asset");
        $span = $this->startSpan("Run update usecase for Template asset");
        try {
            $ref = new TemplateAssetRef($uid);
            $allow = $this->allowUpdate($ref);
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to update Template asset');
            }
            if (!$original = $this->visibility->retrieveVisibleForUpdate($ref)) {
                throw new NotFoundException($uid);
            }
            $this->dispatcher->dispatch(new TemplateAssetUpdateCheck($params, $original));
            $enriched = $this->dispatcher->dispatch(new TemplateAssetUpdateEnrich($params, $original, $params->toAttributes()));
            $attributes = $enriched->getResult();
            $input = $this->visibility->copyWithFixed($attributes);
            $modified = $original->update($input);
            $result = $this->writer->update($original, $modified);
            $output = $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($result));
            return new TemplateAssetUpdateResult($output);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
